<?php
namespace VPM\Booking;
if(!defined('ABSPATH'))exit;
final class Branding {
    public static function defaults():array {return array('brand_name'=>get_bloginfo('name'),'primary'=>'#0057B8','background'=>'#F3F6FA','surface'=>'#FFFFFF','text'=>'#14283F','accent'=>'#C62828','frontend_logo_id'=>0,'email_logo_id'=>0,'sender_name'=>get_bloginfo('name'),'sender_email'=>'','reply_email'=>'');}
    public static function get():array {$defaults=self::defaults();$b=array_merge($defaults,(array)get_option('vpm_booking_branding',array()));foreach(array('primary','background','surface','text','accent')as $key)if(!is_string($b[$key])||!preg_match('/^#[0-9a-fA-F]{6}$/D',$b[$key]))$b[$key]=$defaults[$key];return $b;}
    public static function contrast(string $a,string $b):float {$lum=function($hex){$v=array_map('hexdec',str_split(ltrim($hex,'#'),2));foreach($v as &$n){$n/=255;$n=$n<=0.04045?$n/12.92:pow(($n+0.055)/1.055,2.4);}return .2126*$v[0]+.7152*$v[1]+.0722*$v[2];};$x=$lum($a);$y=$lum($b);return(max($x,$y)+.05)/(min($x,$y)+.05);}
    public static function logo(int $id,bool $email=false):string {if(!$id)return '';Config::require(get_post_type($id)==='attachment'&&in_array(get_post_mime_type($id),$email?array('image/png','image/jpeg'):array('image/png','image/jpeg','image/webp'),true),'invalid_brand_logo');$url=(string)wp_get_attachment_image_url($id,'medium');$uploads=wp_upload_dir();Config::require(wp_parse_url($url,PHP_URL_HOST)===wp_parse_url($uploads['baseurl'],PHP_URL_HOST)&&in_array(wp_parse_url($url,PHP_URL_SCHEME),array('http','https'),true),'invalid_brand_logo');return $url;}
    public static function save(array $d):void {
        Config::require(current_user_can('manage_options'),'permission_denied');$out=self::defaults();foreach(array('brand_name','sender_name')as $key){Config::require(is_string($d[$key]??null)&&strlen($d[$key])<=180,'invalid_brand_name');$out[$key]=trim(sanitize_text_field($d[$key]));Config::require($out[$key]!=='','invalid_brand_name');}
        foreach(array('primary','background','surface','text','accent')as $key){$v=$d[$key]??'';Config::require(is_string($v)&&preg_match('/^#[0-9a-fA-F]{6}$/D',$v),'invalid_brand_color');$out[$key]=strtoupper($v);}
        foreach(array('background','surface')as $bg){Config::require(self::contrast($out['text'],$out[$bg])>=4.5,'brand_text_contrast');Config::require(self::contrast($out['accent'],$out[$bg])>=4.5,'brand_accent_contrast');}
        foreach(array('frontend_logo_id','email_logo_id')as $key){$out[$key]=Commerce::number($d[$key]??0,0);self::logo($out[$key],$key==='email_logo_id');}
        foreach(array('sender_email','reply_email')as $key){$value=$d[$key]??'';Config::require(is_string($value)&&strlen($value)<=254,'invalid_brand_email');$out[$key]=$value===''?'':Config::email($value);}
        update_option('vpm_booking_branding',$out,false);Operations::audit('branding.updated','settings',0);do_action('litespeed_purge_all');
    }
    public static function button_text(array $b):string {return self::contrast($b['primary'],'#FFFFFF')>=4.5?'#FFFFFF':'#000000';}
    public static function public_data():array {$b=self::get();$logo='';try{$logo=self::logo((int)$b['frontend_logo_id']);}catch(\Throwable $e){}return array('name'=>$b['brand_name'],'logo_url'=>$logo,'primary'=>$b['primary'],'primary_text'=>self::button_text($b),'background'=>$b['background'],'surface'=>$b['surface'],'text'=>$b['text'],'accent'=>$b['accent']);}
    public static function mail_data():array {$b=self::get();$url='';try{$url=self::logo((int)$b['email_logo_id'],true);}catch(\Throwable $e){}return array('name'=>$b['brand_name'],'logo_url'=>$url,'primary'=>$b['primary'],'primary_text'=>self::button_text($b),'background'=>$b['background'],'surface'=>$b['surface'],'text'=>$b['text'],'accent'=>$b['accent'],'sender_name'=>$b['sender_name'],'sender_email'=>$b['sender_email'],'reply_email'=>$b['reply_email'],'sender_verified'=>false);}
    public static function email_preview():string {$b=self::mail_data();return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:'.esc_attr($b['surface']).';color:'.esc_attr($b['text']).';font-family:Arial,sans-serif;border:1px solid #d5dfeb"><tr><td style="padding:24px;border-top:6px solid '.esc_attr($b['primary']).'">'.($b['logo_url']?'<img src="'.esc_url($b['logo_url']).'" alt="'.esc_attr($b['name']).'" style="display:block;max-width:180px;max-height:64px">':'<strong>'.esc_html($b['name']).'</strong>').'<h3>Beispiel einer Buchungsbestätigung</h3><p>Hier stehen später die geprüften Buchungsinformationen, Anfahrtshinweise und Kontaktmöglichkeiten.</p><p>Diese Vorschau zeigt das E-Mail-Branding. Sie ist keine Buchung und wurde nicht versendet.</p><p style="padding:14px;background:'.esc_attr($b['primary']).';color:'.esc_attr($b['primary_text']).'">Buchungsinformationen</p></td></tr></table>';}
    public static function header():string {$b=self::public_data();return '<div class="vpm-booking-brand">'.($b['logo_url']?'<img src="'.esc_url($b['logo_url']).'" alt="'.esc_attr($b['name']).'" width="180" height="60" decoding="async">':'<strong>'.esc_html($b['name']).'</strong>').'</div>';}
    public static function css_url():string {return add_query_arg(array('vpm_booking_brand_css'=>'1','v'=>substr(hash('sha256',wp_json_encode(self::public_data())),0,12)),home_url('/'));}
    public static function css():string {$b=self::public_data();return '.vpm-booking-surface{--vpm-b-ink:'.$b['text'].';--vpm-b-gold:'.$b['primary'].';--vpm-b-button-text:'.$b['primary_text'].';--vpm-b-background:'.$b['background'].';--vpm-b-surface:'.$b['surface'].';--vpm-b-accent:'.$b['accent'].';background:var(--vpm-b-background)}.vpm-booking-surface button{color:var(--vpm-b-button-text);border-color:var(--vpm-b-gold)}.vpm-booking-surface :is(.vpm-booking-offer,.vpm-booking-summary,.vpm-customer-details p,.vpm-customer-details section,input,select,textarea){background:var(--vpm-b-surface)}.vpm-booking-surface .vpm-booking-error{color:var(--vpm-b-accent)}.vpm-booking-surface :is(input,select,textarea,button,a):focus-visible{outline-color:var(--vpm-b-ink)}';}
    public static function register():void {
        add_action('template_redirect',function(){if(!isset($_GET['vpm_booking_brand_css']))return;header('Content-Type: text/css; charset=UTF-8');header('X-Content-Type-Options: nosniff');header('X-Robots-Tag: noindex, nofollow');header('Cache-Control: public, max-age=300');echo self::css();exit;},-1);
        add_action('admin_enqueue_scripts',function($hook){if($hook!=='tools_page_vpm-booking-operations'||!current_user_can('manage_options'))return;wp_enqueue_media();$url=plugins_url('',dirname(__DIR__).'/vpm-booking-core.php');wp_enqueue_style('vpm-booking-admin',$url.'/assets/admin.css',array(),'0.11.0');wp_enqueue_script('vpm-booking-brand-admin',$url.'/assets/branding-admin.js',array('jquery','media-views'),'0.11.0',true);});
    }
    public static function admin():void {
        Config::require(current_user_can('manage_options'),'permission_denied');$b=self::get();echo '<h2 id="branding">Branding & Absender</h2><p>Website-Marke pro WordPress-Installation. Die interne Verwaltung bleibt blau. Absenderangaben sind Vorlagen für die Versandstrecke; SMTP, Domainfreigabe und Zustellung werden dadurch nicht eingerichtet.</p><form method="post" class="vpm-brand-settings">';wp_nonce_field('vpm_booking_operations');echo '<input type="hidden" name="vpm_operation" value="branding">';
        foreach(array('brand_name'=>'Markenname im Buchungstool','sender_name'=>'Absendername der E-Mails','sender_email'=>'Geplante Absenderadresse','reply_email'=>'Geplante Plattform-Antwortadresse')as $key=>$label)echo '<label>'.esc_html($label).'<input name="'.esc_attr($key).'" type="'.(str_ends_with($key,'email')?'email':'text').'" value="'.esc_attr($b[$key]).'"></label>';
        echo '<div class="vpm-brand-colors">';foreach(array('primary'=>'Haupt-/Buttonfarbe','background'=>'Hintergrund','surface'=>'Karten und Formulare','text'=>'Schriftfarbe','accent'=>'Fehler-/Warnfarbe')as $key=>$label)echo '<label>'.esc_html($label).'<input type="color" name="'.esc_attr($key).'" value="'.esc_attr($b[$key]).'"></label>';echo '</div><p>Schrift- und Fehlerkontraste werden geprüft. Buttonschrift wird automatisch hell oder dunkel gewählt.</p>';
        foreach(array('frontend_logo_id'=>'Logo im Buchungstool','email_logo_id'=>'Logo in E-Mail-Vorlagen (PNG/JPEG)')as $key=>$label){$src='';try{$src=self::logo((int)$b[$key],$key==='email_logo_id');}catch(\Throwable $e){}echo '<fieldset class="vpm-brand-media"><legend>'.esc_html($label).'</legend><input type="hidden" name="'.esc_attr($key).'" value="'.(int)$b[$key].'"><img class="vpm-brand-logo-preview" '.($src?'src="'.esc_url($src).'"':'hidden').' alt="Logovorschau"><button type="button" class="button vpm-brand-pick">Aus Mediathek wählen</button> <button type="button" class="button vpm-brand-clear">Entfernen</button></fieldset>';}
        submit_button('Branding speichern');echo '</form><details class="vpm-brand-mail-preview"><summary>E-Mail-Design ansehen (Vorschau)</summary>'.self::email_preview().'</details>';
    }
}
